package com.bail.lspfrifa.xposed

/**
 * frida-java-bridge 7.0.13 + buffer@6.0.3 内联（base64-js/ieee754 亦内联）打包单文件 bundle
 * （esbuild-wasm 0.28.2 iife 产物，globalThis.Java 已注入；Buffer 为完整 Uint8Array 实现，不再依赖运行时全局）。
 * base64 分块存储（单字符串超 DEX 64KB 限制），运行时解码为 UTF-8 JS 源码。
 * 用途：GumJS 纯引擎（无内建 Java 桥）下，先于用户脚本评估本 bundle，使 Java.perform/Java.use 可用。
 */
internal object JavaBridgeBundle {
    private val chunks = arrayOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    )
    internal val SCRIPT: String by lazy {
        val b64 = chunks.joinToString("")
        val decoded = String(android.util.Base64.decode(b64, android.util.Base64.NO_WRAP), Charsets.UTF_8)
        // ART35/HyperOS 稳定性补丁（对照"算法助手 Pro"的 patchJavaBridge 机制，代码为原创实现）：
        // 短路 bridge 的 JVMTI env 探测（cachedJvmti 恒 [null]），使 Java.use/Java.choose 走
        // 保守反射 fallback（其 minified 版做等价替换；esbuild 产物中首参名为 vm3，故用宽松正则）。
        decoded.replace(
            Regex("cachedJvmti\\s*=\\s*\\[tryGetEnvJvmti\\([^)]*,\\s*this\\.artRuntime\\)\\]"),
            "cachedJvmti = [null]"
        )
    }
}
